def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Improved version of `equation_v1`."""
    a0, a1, a2, a3, a4, a5, a6 = parameters
    return a0 + a1 * gate_voltage_abs + a2 * drain_voltage_abs + a3 * (gate_voltage_abs ** 2) + a4 * (drain_voltage_abs ** 2) + a5 * (gate_voltage_abs * drain_voltage_abs)
